    (v_id, $q$Cutting Speed$q$, $q$Cutting Speed (m/min)$q$, $q$number$q$, $q$m/min$q$, NULL, NULL, NULL, $q$6$q$, 3, true),
    (v_id, $q$Passes$q$, $q$Passes$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$4$q$, 4, true),
    (v_id, $q$Feed Band Depth$q$, $q$Feed Band Depth (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, $q$0.5$q$, 5, true),
    (v_id, $q$Feed Min$q$, $q$Feed Min (mm/rev)$q$, $q$number$q$, $q$mm/rev$q$, $q$machining_lookup$q$, $q$tblTurningConditions$q$, $q$FeedMinMmPerRev$q$, NULL, 6, true),
    (v_id, $q$Feed Max$q$, $q$Feed Max (mm/rev)$q$, $q$number$q$, $q$mm/rev$q$, $q$machining_lookup$q$, $q$tblTurningConditions$q$, $q$FeedMaxMmPerRev$q$, NULL, 7, true),
    (v_id, $q$Range Position$q$, $q$Range Position$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$0.5$q$, 8, true),
    (v_id, $q$Max Spindle Speed$q$, $q$Max Spindle Speed (rpm)$q$, $q$number$q$, $q$rpm$q$, NULL, NULL, NULL, NULL, 9, true),
    (v_id, $q$Approach Length$q$, $q$Approach Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, $q$4$q$, 10, true),
    (v_id, $q$Feed$q$, $q$Feed (mm/rev)$q$, $q$calculated$q$, $q$mm/rev$q$, NULL, NULL, NULL, $q${Feed Min} + {Range Position} * ({Feed Max} - {Feed Min})$q$, 11, false),
    (v_id, $q$Spindle Speed$q$, $q$Spindle Speed (rpm)$q$, $q$calculated$q$, $q$rpm$q$, NULL, NULL, NULL, $q$min({Max Spindle Speed}, {Cutting Speed} * 1000 / (pi * {Knurl Diameter}))$q$, 12, false),
    (v_id, $q$Machining Time$q$, $q$Machining Time (min)$q$, $q$calculated$q$, $q$min$q$, NULL, NULL, NULL, $q$({Knurl Length} + {Approach Length}) / ({Feed} * {Spindle Speed}) * {Passes}$q$, 13, false),
    (v_id, $q$Tool Price$q$, $q$Tool Price (INR)$q$, $q$number$q$, $q$INR$q$, $q$machining_lookup$q$, $q$tblCuttingToolCost$q$, $q$PriceInr$q$, NULL, 14, true),
    (v_id, $q$Tool Life$q$, $q$Tool Life (parts)$q$, $q$number$q$, $q$parts$q$, $q$machining_lookup$q$, $q$tblCuttingToolCost$q$, $q$ToolLifeParts$q$, NULL, 15, true),
    (v_id, $q$Tool Cost per Part$q$, $q$Tool Cost per Part (INR)$q$, $q$calculated$q$, $q$INR$q$, NULL, NULL, NULL, $q${Tool Price} / {Tool Life}$q$, 16, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$ceil({Machining Time} * 60)$q$, 17, false);

  INSERT INTO public.process_calculator_mappings
    (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
  SELECT 'Machining', s.station, $q$Knurling$q$, v_id, $q$Machining - Knurling$q$, true, 756, s.cls,
         (SELECT pt.id FROM public.process_taxonomy pt WHERE pt.process_group = 'Machining' AND pt.process_name = s.station LIMIT 1)
  FROM (VALUES ($q$2_axis_lathe$q$, $q$2 Axis Lathe$q$), ($q$3_axis_lathe$q$, $q$3 Axis Lathe$q$), ($q$2_axis_bar_feed_lathe_with_sub_spindle$q$, $q$2 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$3_axis_bar_feed_lathe_with_sub_spindle$q$, $q$3 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$simultaneous_turning$q$, $q$Simultaneous Turning$q$), ($q$machining_millturn$q$, $q$MillTurn$q$)) AS s(cls, station)
  ON CONFLICT (process_group, process_route, operation) DO UPDATE
  SET calculator_id = EXCLUDED.calculator_id,
      calculator_name = EXCLUDED.calculator_name,
      machine_class = EXCLUDED.machine_class,
      is_active = true,
      canonical_process_id = EXCLUDED.canonical_process_id;
END
$calc$;

DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Machining - Rough Turning$q$, 19, 6),
    ($q$Machining - Finish Turning$q$, 17, 6),
    ($q$Machining - Parting$q$, 13, 6),
    ($q$Machining - Stock Prep Lathe$q$, 19, 1),
    ($q$Machining - End Facing$q$, 22, 6),
    ($q$Machining - Thread Turning$q$, 15, 6),
    ($q$Machining - Knurling$q$, 17, 6)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.is_active) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1138: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
